using System.Security.AccessControl; using System.Security.Principal; using JazzCapture; using JazzCaptureCore; using JazzCaptureCore.Delivery;
namespace JazzCaptureHostTests;
public sealed class ScreenshotSpoolAclTests:IDisposable { readonly string root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));
 [Fact] public void QueueFilesAndReopenAreCurrentUserOnly(){ CurrentUserOnlyAcl.ApplyDirectory(root); byte[] b=[1]; var q=new ArtifactDeliveryQueue(root,CurrentUserOnlyAcl.ApplyFile); var d=new ArtifactDeliveryDescriptor("a","c","art","art","image/jpeg",Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(b)).ToLowerInvariant(),1,b); var e=new ActivityEvent{SessionId="s",EventId="e",Timestamp="2026-01-01T00:00:00Z",EventType="click",Url="x",ScreenshotId="art"}; var r=q.BindRemoteFile(q.EnqueueScreenshot(d,e,new SessionContext("s",new string('a',32),new string('b',16),e.Timestamp,null,"u","h",null,null)),1); AssertAcl(new DirectoryInfo(root).GetAccessControl()); foreach(var p in Directory.GetFiles(root))AssertAcl(new FileInfo(p).GetAccessControl()); var reopen=new ArtifactDeliveryQueue(root,CurrentUserOnlyAcl.ApplyFile); Assert.NotEmpty(reopen.ReadOtlpBytes(Assert.Single(reopen.Pending()))); }
 static void AssertAcl(FileSystemSecurity s){var id=WindowsIdentity.GetCurrent().User!;Assert.True(s.AreAccessRulesProtected);Assert.All(s.GetAccessRules(true,true,typeof(SecurityIdentifier)).Cast<FileSystemAccessRule>(),x=>Assert.Equal(id,x.IdentityReference));}
 public void Dispose(){if(Directory.Exists(root))Directory.Delete(root,true);}}
